def _reading(setting, channel, displacements):
    ch = setting["channels"][channel]
    total = ch.get("offset", 0)
    for datum, coeff in ch.get("coefficients", {}).items():
        total += coeff * displacements.get(datum, 0)
    return total


def compatible_settings(request):
    """Return {board_id: [setting dicts]} for settings satisfying every calibration.

    Calibration pieces use their complete displacement vectors and inclusive raw
    intervals. Installation physical constraints are not applied here.
    """
    result = {}
    for board in request["boards"]:
        bid = board["id"]
        feasible = []
        for setting in board["settings"]:
            ok = True
            for cal in request.get("calibrations", []):
                if cal.get("board") != bid:
                    continue
                value = _reading(setting, cal["channel"], cal["displacements"])
                low, high = cal["raw"]
                if not (low <= value <= high):
                    ok = False
                    break
            if ok:
                feasible.append(setting)
        result[bid] = feasible
    return result

import itertools


def _reading(setting, channel, x):
    ch = setting["channels"][channel]
    total = ch.get("offset", 0)
    for datum, coeff in ch.get("coefficients", {}).items():
        total += coeff * x.get(datum, 0)
    return total


def _constraint_ok(constraint, x):
    total = 0
    for datum, coeff in constraint.get("coefficients", {}).items():
        total += coeff * x.get(datum, 0)
    return constraint["min"] <= total <= constraint["max"]


def setup_ranges(request, setup, chosen):
    """Return {gauge_id: [min, max]} over feasible integer vectors, or None.

    Feasibility requires the inclusive global bounds, common physical
    constraints, setup constraints, and installation readings under the fixed
    board selection.
    """
    bounds = request["bounds"]
    datums = list(bounds.keys())
    intervals = [range(bounds[d][0], bounds[d][1] + 1) for d in datums]

    common = request.get("physical_constraints", [])
    setup_constraints = setup.get("constraints", [])
    readings = setup.get("readings", [])

    gauges = request["gauges"]

    mins = {g["id"]: None for g in gauges}
    maxs = {g["id"]: None for g in gauges}
    found = False

    for combo in itertools.product(*intervals):
        x = dict(zip(datums, combo))
        ok = True
        for c in common:
            if not _constraint_ok(c, x):
                ok = False
                break
        if not ok:
            continue
        for c in setup_constraints:
            if not _constraint_ok(c, x):
                ok = False
                break
        if not ok:
            continue
        for r in readings:
            setting = chosen[r["board"]]
            value = _reading(setting, r["channel"], x)
            low, high = r["raw"]
            if not (low <= value <= high):
                ok = False
                break
        if not ok:
            continue
        found = True
        for g in gauges:
            gid = g["id"]
            value = g.get("base", 0)
            for datum, coeff in g.get("coefficients", {}).items():
                value += coeff * x.get(datum, 0)
            if mins[gid] is None or value < mins[gid]:
                mins[gid] = value
            if maxs[gid] is None or value > maxs[gid]:
                maxs[gid] = value

    if not found:
        return None
    return {gid: [mins[gid], maxs[gid]] for gid in mins}

