def transform(payload, contract):
    """Return the business report described in SPEC.md. Leave caller inputs unchanged."""
    request = payload["request"]

    compatible = compatible_settings(request)

    boards = request["boards"]
    board_ids = [b["id"] for b in boards]
    settings_lists = [compatible[bid] for bid in board_ids]

    setups = request["setups"]

    best_cost = None
    best_selections = []  # list of tuples of setting dicts aligned with board_ids

    for combo in itertools.product(*settings_lists):
        chosen = dict(zip(board_ids, combo))
        cost = sum(s["penalty"] for s in combo)
        if best_cost is not None and cost > best_cost:
            continue
        feasible = True
        for setup in setups:
            if setup_ranges(request, setup, chosen) is None:
                feasible = False
                break
        if not feasible:
            continue
        if best_cost is None or cost < best_cost:
            best_cost = cost
            best_selections = [combo]
        elif cost == best_cost:
            best_selections.append(combo)

    if best_cost is None:
        return {"minimum_cost": None, "setting_options": {}, "ranges": {}}

    setting_options = {}
    for i, bid in enumerate(board_ids):
        ids = []
        for sel in best_selections:
            sid = sel[i]["id"]
            if sid not in ids:
                ids.append(sid)
        setting_options[bid] = ids

    ranges = {}
    for setup in setups:
        sid = setup["id"]
        mins = {}
        maxs = {}
        for g in request["gauges"]:
            mins[g["id"]] = None
            maxs[g["id"]] = None
        for sel in best_selections:
            chosen = dict(zip(board_ids, sel))
            r = setup_ranges(request, setup, chosen)
            if r is None:
                continue
            for gid, (lo, hi) in r.items():
                if mins[gid] is None or lo < mins[gid]:
                    mins[gid] = lo
                if maxs[gid] is None or hi > maxs[gid]:
                    maxs[gid] = hi
        ranges[sid] = {gid: [mins[gid], maxs[gid]] for gid in mins}

    return {
        "minimum_cost": best_cost,
        "setting_options": setting_options,
        "ranges": ranges,
    }


def load_payload(path):
    return read(path)


def build_component(root, contract):
    return build(root, contract, transform)

