from runtime import read
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent.parent


def _load_request():
    return read(ROOT / "inputs" / "request.json")


def _call_transform(payload):
    from packages.analysis.engine import transform
    return transform(payload, {"task": "I06"})


class TestPublicExample(unittest.TestCase):
