    def test_no_shared_selection_returns_null(self):
        req = _load_request()
        # Force every board setting to fail calibration so no selection exists.
        req["calibrations"].append({
            "board": "A", "channel": "signal",
            "displacements": {"x": 0, "y": 0}, "raw": [100, 100],
        })
        result = _call_transform({"request": req})
        self.assertIsNone(result["minimum_cost"])
        self.assertEqual(result["setting_options"], {})
        self.assertEqual(result["ranges"], {})


class TestInputsUnchanged(unittest.TestCase):
    def test_caller_inputs_not_mutated(self):
        payload = {"request": _load_request()}
        snapshot = read(ROOT / "inputs" / "request.json")
        _call_transform(payload)
        self.assertEqual(payload["request"], snapshot)


if __name__ == "__main__":
